import io.netty.channel.Channel;
import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import org.traccar.Protocol;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;
import org.traccar.model.Position;
import org.mockito.Mockito;
import java.nio.charset.StandardCharsets;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class WatchProtocolDecoderTest {

    @Test
    public void getHasIndexDefaultTest() {
        Protocol protocol = Mockito.mock(Protocol.class);
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);
        assertFalse(decoder.getHasIndex());
    }

    @Test
    public void getManufacturerDefaultTest() {
        Protocol protocol = Mockito.mock(Protocol.class);
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);
        assertEquals(null, decoder.getManufacturer());
    }

    @Test
    public void decodeHeartBeatTest() throws Exception {
        Protocol protocol = Mockito.mock(Protocol.class);
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        ByteBuf buf = Unpooled.copiedBuffer("[3G*1234567890*0002*LK]", StandardCharsets.US_ASCII);
        Channel channel = Mockito.mock(Channel.class);

        Position position = (Position) decoder.decode(channel, null, buf);

        assertNull(position);
    }

    @Test
    public void decodeLocationDataTest() throws Exception {
        Protocol protocol = Mockito.mock(Protocol.class);
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        ByteBuf buf = Unpooled.copiedBuffer("[3G*1234567890*0024*LK94669920190509185028]", StandardCharsets.US_ASCII);
        Channel channel = Mockito.mock(Channel.class);

        Position position = (Position) decoder.decode(channel, null, buf);

        assertNotNull(position);
    }

    @Test
    public void decodeInvalidDataTest() throws Exception {
        Protocol protocol = Mockito.mock(Protocol.class);
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        ByteBuf buf = Unpooled.copiedBuffer("[3G*1234567890*0000*UN]", StandardCharsets.US_ASCII);
        Channel channel = Mockito.mock(Channel.class);

        Position position = (Position) decoder.decode(channel, null, buf);

        assertNull(position);
    }

}
